package com.edgecloud.device.service; import com.edgecloud.device.dto.HeartbeatPolicyResult;import com.edgecloud.device.entity.HeartbeatStatus;import java.time.*;import org.springframework.stereotype.Service;
@Service public class HeartbeatPolicyServiceImpl implements HeartbeatPolicyService {
 public HeartbeatPolicyResult calculate(LocalDateTime last,LocalDateTime since,int interval,int timeout,LocalDateTime now){if(interval<1||timeout<=interval)throw new IllegalArgumentException("Heartbeat timeout must be greater than heartbeat interval");if(last==null)return new HeartbeatPolicyResult(HeartbeatStatus.UNKNOWN,null,0,null);long age=Math.max(0,Duration.between(last,now).getSeconds());HeartbeatStatus status=age<=interval?HeartbeatStatus.ONLINE:age<=2L*interval?HeartbeatStatus.HEALTHY:age<=timeout?HeartbeatStatus.DELAYED:HeartbeatStatus.OFFLINE;int missed=(int)Math.min(Integer.MAX_VALUE,age/interval);Duration connected=since==null?null:Duration.between(since,now).isNegative()?Duration.ZERO:Duration.between(since,now);return new HeartbeatPolicyResult(status,last.plusSeconds(interval),missed,connected);}
}
